import { StrictMode } from 'react';
import { createRoot } from 'react-dom/client';
import App from './App.tsx';
import ErrorBoundary from './components/ErrorBoundary';
import './index.css';

const container = document.getElementById('root');
if (!container) {
  // index.html is generated by Vite and always has #root, but a missing mount
  // point used to produce a silent blank page with only a non-null assertion
  // to blame. Say so instead.
  throw new Error('LandCraft could not start: #root is missing from index.html.');
}

createRoot(container).render(
  <StrictMode>
    {/*
      Without this, any render-time throw unmounted the entire tree and left a
      blank page. The editor's autosave means the user's plan usually survives
      a reload, but they had no way to know that or to get back.
    */}
    <ErrorBoundary>
      <App />
    </ErrorBoundary>
  </StrictMode>,
);
